def sort_array(arr):
    """
    Sorts an array of integers based on the count of ones in their binary 
    representation (ascending), and then by their decimal value (ascending).
    """
    def count_ones(n):
        # Handle negative numbers by using their bit representation 
        # or standard bin() behavior. However, the prompt specifies 
        # "non-negative integers" in the text but provides negative 
        # examples. Standard bit_count() or bin().count('1') 
        # is used for the magnitude.
        if n < 0:
            # For negative numbers, we treat them as their 2's complement 
            # or simply use the absolute value's bits as per common 
            # competitive programming logic unless specified.
            # Given the examples, we use bin(n).count('1') logic.
            return bin(n).count('1')
        return bin(n).count('1')

    # Sort by (count of ones, decimal value)
    return sorted(arr, key=lambda x: (count_ones(x), x))

def sort_array(arr):
    """
    Sorts an array of integers based on the number of ones in their binary representation.
    If the count of ones is the same, sorts by the decimal value.
    Note: For negative numbers, bin() returns a string starting with '-0b', 
    so we use bit_count() or bin() on the absolute value to count ones.
    """
    def sort_key(x):
        # bin(x).count('1') works for positive integers.
        # For negative integers, the task implies counting bits of the representation.
        # Standard behavior for this specific logic is usually bit_count on absolute value.
        return (bin(x).count('1'), x)

    return sorted(arr, key=sort_key)

def select_words(s, n):
    """Given a string s and a natural number n, you have been tasked to implement 
    a function that returns a list of all words from string s that contain exactly 
    n consonants, in order these words appear in the string s.
    If the string s is empty then the function should return an empty list.
    Note: you may assume the input string contains only letters and spaces.
    """
    if not s:
        return []

    vowels = "aeiouAEIOU"
    words = s.split()
    result = []

    for word in words:
        consonant_count = 0
        for char in word:
            if char.isalpha() and char not in vowels:
                consonant_count += 1

        if consonant_count == n:
            result.append(word)

    return result

