def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    # Iterate from the right side (excluding the very last character)
    # We need a vowel that has a consonant to its left and a consonant to its right.
    # Therefore, the vowel cannot be at index 0 or index len(word)-1.
    for i in range(len(word) - 2, 0, -1):
        char = word[i]
        if char in vowels:
            left_char = word[i-1]
            right_char = word[i+1]
            if left_char not in vowels and right_char not in vowels:
                return char
    return ""

def match_parens(lst):
    """
    Checks if concatenating two strings of parentheses in any order
    results in a balanced string.
    """
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    s1, s2 = lst[0], lst[1]

    # Try both possible concatenations
    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'
    else:
        return 'No'

