def valid_date(date):
    """You have to write a function which validates a given date string and
    returns True if the date is valid otherwise False.
    """
    # Rule 1: The date string is not empty.
    if not date:
        return False

    # Rule 4: The date should be in the format: mm-dd-yyyy
    # We check if the string has exactly 10 characters and follows the pattern
    parts = date.split('-')
    if len(parts) != 3 or len(parts[0]) != 2 or len(parts[1]) != 2 or len(parts[2]) != 4:
        return False

    # Ensure all parts are numeric
    if not (parts[0].isdigit() and parts[1].isdigit() and parts[2].isdigit()):
        return False

    month = int(parts[0])
    day = int(parts[1])
    year = int(parts[2])

    # Rule 3: The months should not be less than 1 or higher than 12.
    if month < 1 or month > 12:
        return False

    # Rule 2: The number of days constraints
    # Months 1, 3, 5, 7, 8, 10, 12 -> 1-31 days
    # Months 4, 6, 9, 11 -> 1-30 days
    # Month 2 -> 1-29 days
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if not (1 <= day <= 31):
            return False
    elif month in [4, 6, 9, 11]:
        if not (1 <= day <= 30):
            return False
    elif month == 2:
        if not (1 <= day <= 29):
            return False

    return True

