import re

def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 
    """
    # First, identify if there are any occurrences of 3 or more spaces
    has_triple_spaces = bool(re.search(r' {3,}', text))

    if has_triple_spaces:
        # Replace all sequences of 1 or more spaces with a single dash
        return re.sub(r' +', '-', text)
    else:
        # Replace all single spaces with underscores
        return text.replace(' ', '_')

