    """Your task is to write a function that returns true if a number x is a simple
    power of n and false in other cases.
    x is a simple power of n if n**int=x
    """
    if n == 1:
        return x == 1

    # Handle cases where x is less than 1 or n is 0/negative
    if x < 1:
        return False

    # Check powers of n starting from n**0
    current = 1
    while current <= x:
        if current == x:
            return True
        current *= n
        # Safety break for n=0 or n=1 (though n=1 is handled above)
        if n <= 1 and current == x:
            break

    return False

