def get_row(lst, x):
    """
    Finds integers x in a 2D nested list and returns a list of (row, col) tuples.
    Sorted by row ascending, then by column descending.
    """
    results = []
    for r_idx, row in enumerate(lst):
        for c_idx, value in enumerate(row):
            if value == x:
                results.append((r_idx, c_idx))

    # Sort by row (index 0) ascending, then by column (index 1) descending
    results.sort(key=lambda coord: (coord[0], -coord[1]))
    return results

def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated. 
    The alphabet should be rotated in a manner such that the letters 
    shift down by two multiplied to two places.
    """
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            # Shift by 4 (2 * 2)
            new_char = chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
            result.append(new_char)
        elif 'A' <= char <= 'Z':
            # Shift by 4 (2 * 2)
            new_char = chr((ord(char) - ord('A') + 4) % 26 + ord('A'))
            result.append(new_char)
        else:
            result.append(char)
    return "".join(result)

