def encode(message):
    vowels = 'aeiouAEIOU'
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    result = []

    for char in message:
        if char.isalpha():
            # Swap case
            is_upper = char.isupper()
            base_char = char.lower()

            # Check if it's a vowel
            if base_char in 'aeiou':
                # Find index in alphabet and move 2 places ahead
                idx = alphabet.find(base_char)
                new_char = alphabet[(idx + 2) % 26]
                # Apply swapped case
                result.append(new_char.upper() if not is_upper else new_char.lower())
            else:
                # Not a vowel, just swap case
                result.append(base_char.upper() if not is_upper else base_char.lower())
        else:
            # Non-alphabetic characters (spaces, etc.)
            result.append(char)

    return "".join(result)

