import math

def closest_integer(value):
    """
    Takes a value (string) representing a number and returns the closest integer to it.
    If the number is equidistant from two integers, it rounds away from zero.
    """
    num = float(value)
    lower = math.floor(num)
    upper = math.ceil(num)

    if lower == upper:
        return lower

    dist_lower = abs(num - lower)
    dist_upper = abs(num - upper)

    if dist_upper < dist_lower:
        return upper
    elif dist_lower < dist_upper:
        return lower
    else:
        # Equidistant case: round away from zero
        if num >= 0:
            return upper
        else:
            return lower
